using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;using UnityEngine.AI;using Unity.AI.Navigation;
namespace TwinkleOps.Editor {
public static class V12Connections {
 const string Root="Assets/TwinkleOps/Content/V12";static Transform parent;static Material metal;static int id;
 public static void Apply(){EditorSceneManager.OpenScene("Assets/TwinkleOps/Scenes/InfectionZone.unity");if(GameObject.Find("V12 Roof connection"))throw new Exception("Roof connection already exists");parent=new GameObject("V12 Roof connection").transform;metal=AssetDatabase.LoadAssetAtPath<Material>("Assets/ThirdParty/V12/modular_factory_facade/Factory trim.mat");
  var vs=new List<Vector3>();var ts=new List<int>();var uv=new List<Vector2>();
  void Face(Vector3 a,Vector3 b,Vector3 c,Vector3 d){int n=vs.Count;vs.AddRange(new[]{a,b,c,d,a,b,c,d});for(int i=0;i<2;i++)uv.AddRange(new[]{Vector2.zero,new Vector2(1,0),Vector2.one,new Vector2(0,1)});ts.AddRange(new[]{n,n+1,n+2,n,n+2,n+3,n+6,n+5,n+4,n+7,n+6,n+4});}
  const int steps=22;for(int i=0;i<steps;i++){float z=54+i*.32f,y=(i+1)*(3.12f/steps),prev=i*(3.12f/steps);Face(new(33,y,z),new(33,y,z+.32f),new(35,y,z+.32f),new(35,y,z));Face(new(33,prev,z),new(35,prev,z),new(35,y,z),new(33,y,z));}
  MeshObject("Roof service staircase",vs,ts,uv,true);
  Beam("Left stringer",new(33,0,54),new(33,3.12f,61.04f),.11f);Beam("Right stringer",new(35,0,54),new(35,3.12f,61.04f),.11f);
  foreach(float x in new[]{33f,35f}){Beam("Stair handrail",new(x,1.05f,54),new(x,4.17f,61.04f),.05f);for(int i=0;i<6;i++){float f=i/5f;Beam("Stair post",new(x,3.12f*f,54+7.04f*f),new(x,3.12f*f+1.05f,54+7.04f*f),.035f);}}
  vs.Clear();ts.Clear();uv.Clear();Face(new(42,3.12f,56.8f),new(42,3.12f,61.2f),new(46,3.12f,61.2f),new(46,3.12f,56.8f));MeshObject("Diagnostics footbridge",vs,ts,uv,true);
  foreach(float x in new[]{42f,46f}){Beam("Bridge rail",new(x,4.15f,56.8f),new(x,4.15f,61.2f),.05f);foreach(float z in new[]{56.8f,59,61.2f})Beam("Bridge post",new(x,3.12f,z),new(x,4.15f,z),.035f);var o=new GameObject("Bridge safety collision");o.transform.SetParent(parent);var c=o.AddComponent<BoxCollider>();c.center=new Vector3(x,3.65f,59);c.size=new Vector3(.12f,1.1f,4.4f);}
  var waypoint=new GameObject("V12 route rooftop");waypoint.transform.SetParent(parent);waypoint.transform.position=new Vector3(44,3.15f,54);
  var safe=UnityEngine.Object.FindObjectsByType<LootContainer>(FindObjectsSortMode.None).First(b=>b.kind==ContainerKind.Safe&&b.transform.position.x>50);safe.transform.position=new Vector3(47,3.11f,36);safe.displayName="诊疗楼顶保险箱";
  foreach(var e in UnityEngine.Object.FindObjectsByType<ExtractionZone>(FindObjectsSortMode.None)){if(e.displayName.Contains("车库")){e.condition=ExtractionCondition.Lightweight;e.weightLimit=8;}else if(e.displayName.Contains("仓储")){e.condition=ExtractionCondition.Signal;e.signalDelay=90;}}
  foreach(var box in UnityEngine.Object.FindObjectsByType<LootContainer>(FindObjectsSortMode.None)){var col=box.GetComponent<BoxCollider>();if(!col)continue;var obstacle=box.GetComponent<NavMeshObstacle>();if(!obstacle)obstacle=box.gameObject.AddComponent<NavMeshObstacle>();obstacle.shape=NavMeshObstacleShape.Box;obstacle.center=col.center;obstacle.size=col.size;obstacle.carving=true;obstacle.carvingTimeToStationary=.1f;}
  foreach(var r in parent.GetComponentsInChildren<MeshRenderer>())r.gameObject.isStatic=true;var surface=UnityEngine.Object.FindFirstObjectByType<NavMeshSurface>();surface.BuildNavMesh();AssetDatabase.CreateAsset(surface.navMeshData,Root+"/ConnectedNavigation.asset");
  PlayerSettings.bundleVersion="1.2.0-alpha";EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());AssetDatabase.SaveAssets();V12Map.Review();
 }
 static void MeshObject(string name,List<Vector3> vs,List<int> ts,List<Vector2> uv,bool collider){var m=new Mesh{name=name};m.SetVertices(vs);m.SetTriangles(ts,0);m.SetUVs(0,uv);m.RecalculateNormals();m.RecalculateTangents();AssetDatabase.CreateAsset(m,Root+"/Connection"+(id++)+".asset");var o=new GameObject(name);o.transform.SetParent(parent);o.AddComponent<MeshFilter>().sharedMesh=m;o.AddComponent<MeshRenderer>().sharedMaterial=metal;if(collider)o.AddComponent<MeshCollider>().sharedMesh=m;}
 static void Beam(string name,Vector3 a,Vector3 b,float width){Vector3 along=(b-a).normalized,side=Vector3.Cross(along,Vector3.right).normalized;if(side.sqrMagnitude<.1f)side=Vector3.up;Vector3 up=Vector3.Cross(along,side).normalized;side*=width/2;up*=width/2;var v=new List<Vector3>{a-side-up,a+side-up,a+side+up,a-side+up,b-side-up,b+side-up,b+side+up,b-side+up};var tris=new List<int>{0,2,1,0,3,2,4,5,6,4,6,7,0,1,5,0,5,4,1,2,6,1,6,5,2,3,7,2,7,6,3,0,4,3,4,7};MeshObject(name,v,tris,Enumerable.Range(0,8).Select(i=>new Vector2(i%2,i/2f)).ToList(),false);}
}}
